import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { getArticle, likeArticle, addArticleComment, updateArticle, deleteArticle } from '../services/api';

function ArticleDetail({ user }) {
  const { id } = useParams();
  const navigate = useNavigate();
  const [article, setArticle] = useState(null);
  const [comment, setComment] = useState('');
  const [isLiked, setIsLiked] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editTitle, setEditTitle] = useState('');
  const [editContent, setEditContent] = useState('');
  const [editMoodCategory, setEditMoodCategory] = useState('');
  const [editKeywords, setEditKeywords] = useState('');

  const fetchArticle = async () => {
    try {
      const data = await getArticle(id);
      setArticle(data);
      setEditTitle(data.title);
      setEditContent(data.content);
      setEditMoodCategory(data.mood_category || '');
      setEditKeywords(data.keywords || '');
    } catch (error) {
      console.error('Error:', error);
    }
  };

  useEffect(() => {
    fetchArticle();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id]);

  const handleLike = async () => {
    if (!user) {
      navigate('/login');
      return;
    }
    try {
      const result = await likeArticle(id);
      setIsLiked(result.liked);
      fetchArticle();
    } catch (error) {
      console.error('Error:', error);
    }
  };

  const handleComment = async (e) => {
    e.preventDefault();
    if (!user) {
      navigate('/login');
      return;
    }
    if (!comment.trim()) return;
    
    try {
      await addArticleComment(id, { content: comment });
      setComment('');
      fetchArticle();
    } catch (error) {
      console.error('Error:', error);
    }
  };

  const handleEdit = () => {
    setIsEditing(true);
  };

  const handleCancelEdit = () => {
    setIsEditing(false);
    setEditTitle(article.title);
    setEditContent(article.content);
    setEditMoodCategory(article.mood_category || '');
    setEditKeywords(article.keywords || '');
  };

  const handleSaveEdit = async (e) => {
    e.preventDefault();
    if (!editTitle.trim() || !editContent.trim()) {
      alert('Title and content are required');
      return;
    }

    try {
      await updateArticle(id, {
        title: editTitle,
        content: editContent,
        mood_category: editMoodCategory,
        keywords: editKeywords
      });
      setIsEditing(false);
      fetchArticle();
      alert('Article updated successfully!');
    } catch (error) {
      console.error('Error:', error);
      alert('Failed to update article');
    }
  };

  const handleDelete = async () => {
    if (!window.confirm('Are you sure you want to delete this article? This action cannot be undone.')) {
      return;
    }

    try {
      await deleteArticle(id);
      alert('Article deleted successfully');
      navigate('/articles');
    } catch (error) {
      console.error('Error:', error);
      alert('Failed to delete article');
    }
  };

  if (!article) return <div className="loading">Loading...</div>;

  return (
    <div className="container">
      <div style={{
        background: 'white',
        borderRadius: '20px',
        padding: '3rem',
        boxShadow: '0 4px 20px rgba(0,0,0,0.1)'
      }}>
        {/* Header with author info and edit/delete buttons */}
        <div style={{ 
          display: 'flex', 
          justifyContent: 'space-between', 
          alignItems: 'flex-start',
          marginBottom: '2rem',
          paddingBottom: '1rem',
          borderBottom: '2px solid #f0f0f0'
        }}>
          <div style={{ flex: 1 }}>
            {isEditing ? (
              <input
                type="text"
                value={editTitle}
                onChange={(e) => setEditTitle(e.target.value)}
                style={{
                  width: '100%',
                  fontSize: '2rem',
                  fontWeight: 'bold',
                  border: '2px solid #667eea',
                  borderRadius: '10px',
                  padding: '0.5rem',
                  marginBottom: '0.5rem'
                }}
              />
            ) : (
              <h1 style={{ margin: 0, marginBottom: '0.5rem' }}>{article.title}</h1>
            )}
            <p style={{ margin: 0, color: '#666' }}>
              By{' '}
              <span 
                onClick={() => navigate(`/users/${article.author.user.id}`)}
                style={{ cursor: 'pointer', color: '#7F7FD5', fontWeight: 'bold' }}
              >
                Dr. {article.author.user.username}
              </span>
              {' • '}
              {new Date(article.created_at).toLocaleDateString()}
            </p>
            {!isEditing && article.keywords && (
              <p style={{ margin: '0.5rem 0 0 0', color: '#999', fontSize: '0.9rem' }}>
                Keywords: {article.keywords}
              </p>
            )}
          </div>

          {article.is_author && (
            <div style={{ display: 'flex', gap: '0.5rem', marginLeft: '1rem' }}>
              {!isEditing ? (
                <>
                  <button
                    onClick={handleEdit}
                    style={{
                      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                      color: 'white',
                      border: 'none',
                      padding: '0.6rem 1.2rem',
                      borderRadius: '20px',
                      cursor: 'pointer',
                      fontWeight: 'bold'
                    }}
                  >
                    ✏️ Edit
                  </button>
                  <button
                    onClick={handleDelete}
                    style={{
                      background: 'linear-gradient(135deg, #ff6b6b 0%, #ee5a6f 100%)',
                      color: 'white',
                      border: 'none',
                      padding: '0.6rem 1.2rem',
                      borderRadius: '20px',
                      cursor: 'pointer',
                      fontWeight: 'bold'
                    }}
                  >
                    🗑️ Delete
                  </button>
                </>
              ) : (
                <>
                  <button
                    onClick={handleSaveEdit}
                    style={{
                      background: 'linear-gradient(135deg, #56ab2f 0%, #a8e063 100%)',
                      color: 'white',
                      border: 'none',
                      padding: '0.6rem 1.2rem',
                      borderRadius: '20px',
                      cursor: 'pointer',
                      fontWeight: 'bold'
                    }}
                  >
                    ✓ Save
                  </button>
                  <button
                    onClick={handleCancelEdit}
                    style={{
                      background: '#ccc',
                      color: '#333',
                      border: 'none',
                      padding: '0.6rem 1.2rem',
                      borderRadius: '20px',
                      cursor: 'pointer',
                      fontWeight: 'bold'
                    }}
                  >
                    ✕ Cancel
                  </button>
                </>
              )}
            </div>
          )}
        </div>

        {/* Article content or edit form */}
        {isEditing ? (
          <div>
            <div style={{ marginBottom: '1rem' }}>
              <label style={{ display: 'block', marginBottom: '0.5rem', fontWeight: 'bold' }}>
                Mood Category (optional)
              </label>
              <select
                value={editMoodCategory}
                onChange={(e) => setEditMoodCategory(e.target.value)}
                style={{
                  width: '100%',
                  padding: '0.8rem',
                  borderRadius: '10px',
                  border: '2px solid #e0e0e0',
                  fontSize: '1rem'
                }}
              >
                <option value="">Select mood category</option>
                <option value="happy">Happy</option>
                <option value="sad">Sad</option>
                <option value="anxious">Anxious</option>
                <option value="stressed">Stressed</option>
                <option value="neutral">Neutral</option>
              </select>
            </div>

            <div style={{ marginBottom: '1rem' }}>
              <label style={{ display: 'block', marginBottom: '0.5rem', fontWeight: 'bold' }}>
                Keywords (comma-separated, optional)
              </label>
              <input
                type="text"
                value={editKeywords}
                onChange={(e) => setEditKeywords(e.target.value)}
                placeholder="e.g. anxiety, depression, wellness"
                style={{
                  width: '100%',
                  padding: '0.8rem',
                  borderRadius: '10px',
                  border: '2px solid #e0e0e0',
                  fontSize: '1rem'
                }}
              />
            </div>

            <div style={{ marginBottom: '1rem' }}>
              <label style={{ display: 'block', marginBottom: '0.5rem', fontWeight: 'bold' }}>
                Content
              </label>
              <textarea
                value={editContent}
                onChange={(e) => setEditContent(e.target.value)}
                rows="20"
                style={{
                  width: '100%',
                  padding: '1rem',
                  borderRadius: '10px',
                  border: '2px solid #e0e0e0',
                  fontSize: '1rem',
                  fontFamily: 'inherit',
                  lineHeight: '1.8'
                }}
              />
            </div>
          </div>
        ) : (
          <div style={{ 
            whiteSpace: 'pre-wrap', 
            marginTop: '2rem',
            lineHeight: '1.8',
            fontSize: '1.1rem'
          }}>
            {article.content}
          </div>
        )}
        
        {/* Action buttons (only show when not editing) */}
        {!isEditing && (
          <div className="action-buttons" style={{ 
            marginTop: '3rem',
            paddingTop: '2rem',
            borderTop: '2px solid #f0f0f0',
            display: 'flex',
            gap: '1rem'
          }}>
            <button 
              onClick={handleLike} 
              className="like-btn"
              style={{
                background: isLiked ? '#4CAF50' : 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                color: 'white',
                border: 'none',
                padding: '0.8rem 1.5rem',
                borderRadius: '25px',
                cursor: 'pointer',
                fontWeight: 'bold',
                fontSize: '1rem',
                display: 'flex',
                alignItems: 'center',
                gap: '0.5rem'
              }}
            >
              👍 {article.like_count} {article.like_count === 1 ? 'Like' : 'Likes'}
            </button>
            <div style={{
              color: '#666',
              display: 'flex',
              alignItems: 'center',
              padding: '0.8rem 1.5rem'
            }}>
              💬 {article.comment_count} {article.comment_count === 1 ? 'Comment' : 'Comments'}
            </div>
          </div>
        )}

        {/* Comments section (only show when not editing) */}
        {!isEditing && (
          <div className="comments-section" style={{ marginTop: '3rem' }}>
            <h2 style={{ marginBottom: '1.5rem' }}>Comments</h2>
            
            {user && (
              <form onSubmit={handleComment} style={{ marginBottom: '2rem' }}>
                <textarea
                  value={comment}
                  onChange={(e) => setComment(e.target.value)}
                  placeholder="Share your thoughts on this article..."
                  rows="4"
                  style={{ 
                    width: '100%', 
                    padding: '1rem', 
                    borderRadius: '15px',
                    border: '2px solid #e0e0e0',
                    fontSize: '1rem',
                    fontFamily: 'inherit',
                    resize: 'vertical'
                  }}
                />
                <button 
                  type="submit" 
                  className="submit-btn" 
                  style={{ 
                    marginTop: '1rem',
                    background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                    color: 'white',
                    border: 'none',
                    padding: '0.8rem 2rem',
                    borderRadius: '25px',
                    cursor: 'pointer',
                    fontWeight: 'bold',
                    fontSize: '1rem'
                  }}
                >
                  Post Comment
                </button>
              </form>
            )}

            {!user && (
              <div style={{
                padding: '1.5rem',
                background: '#f8f9fa',
                borderRadius: '15px',
                textAlign: 'center',
                marginBottom: '2rem'
              }}>
                <p style={{ margin: 0 }}>
                  <span 
                    onClick={() => navigate('/login')}
                    style={{ 
                      color: '#7F7FD5', 
                      cursor: 'pointer',
                      fontWeight: 'bold',
                      textDecoration: 'underline'
                    }}
                  >
                    Login
                  </span>
                  {' '}to like and comment on this article
                </p>
              </div>
            )}

            {article.comments && article.comments.length > 0 ? (
              article.comments.map(c => (
                <div 
                  key={c.id} 
                  className="comment" 
                  style={{ 
                    marginTop: '1rem', 
                    padding: '1.5rem', 
                    background: '#f8f9fa', 
                    borderRadius: '15px'
                  }}
                >
                  <div style={{ 
                    display: 'flex', 
                    justifyContent: 'space-between',
                    marginBottom: '0.5rem'
                  }}>
                    <strong 
                      onClick={() => navigate(`/users/${c.user.id}`)}
                      style={{ 
                        cursor: 'pointer', 
                        color: '#7F7FD5'
                      }}
                    >
                      {c.user.username}
                    </strong>
                    <span style={{ fontSize: '0.9rem', color: '#999' }}>
                      {new Date(c.created_at).toLocaleDateString()}
                    </span>
                  </div>
                  <p style={{ margin: 0, lineHeight: '1.6' }}>{c.content}</p>
                </div>
              ))
            ) : (
              <div style={{ 
                textAlign: 'center', 
                padding: '2rem', 
                color: '#999' 
              }}>
                No comments yet. Be the first to share your thoughts!
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

export default ArticleDetail;
